script:
(function () {
  'use strict';
  // Financial ratios from one period's income statement and end-of-period balance sheet.
  //   Gross profit = revenue - COGS; operating income = gross profit - operating expenses;
  //   pre-tax income = operating income + other income - interest; net income = pre-tax - taxes.
  //   Equity = total assets - total liabilities. Ratios with a zero (or, for ROE and debt-to-equity,
  //   negative) denominator show "n/a" instead of a number.
  // Verified (Node scratch test, hand-checked): revenue $1,000,000, COGS $600,000, operating
  // expenses $250,000, interest $20,000, taxes $30,000, cash $50,000, receivables $80,000,
  // inventory $120,000, current assets $270,000, total assets $600,000, current liabilities
  // $150,000, total liabilities $350,000 -> gross margin 40.0%, operating margin 15.0%, net margin
  // 10.0%, current 1.80, quick 1.00, cash 0.33, D/E 1.40, debt ratio 58.3%, interest coverage 7.50,
  // ROA 16.7%, ROE 40.0%, asset turnover 1.67, inventory turnover 5.00 (73.0 days), receivables
  // turnover 12.50 (29.2 days). All-zero and negative-equity inputs show n/a, never NaN/Infinity.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var dec = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var one = new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });

  var FIELDS = ['frCash', 'frReceivables', 'frInventory', 'frCurAssets', 'frAssets', 'frCurLiab', 'frLiab',
                'frRevenue', 'frCogs', 'frOpex', 'frInterest', 'frOther', 'frTaxes'];

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function div(a, b) { return b > 0 ? a / b : null; }

  function compute(v) {
    var gross = v.revenue - v.cogs;
    var operating = gross - v.opex;
    var pretax = operating + v.other - v.interest;
    var net = pretax - v.taxes;
    var equity = v.assets - v.liab;
    var invTurn = div(v.cogs, v.inventory), recTurn = div(v.revenue, v.receivables);
    return {
      gross: gross, operating: operating, pretax: pretax, net: net, equity: equity,
      workingCapital: v.curAssets - v.curLiab,
      current: div(v.curAssets, v.curLiab),
      quick: div(v.curAssets - v.inventory, v.curLiab),
      cash: div(v.cash, v.curLiab),
      grossMargin: div(gross, v.revenue),
      operatingMargin: div(operating, v.revenue),
      netMargin: div(net, v.revenue),
      roa: div(net, v.assets),
      roe: div(net, equity),
      debtToEquity: div(v.liab, equity),
      debtRatio: div(v.liab, v.assets),
      interestCoverage: div(operating, v.interest),
      assetTurnover: div(v.revenue, v.assets),
      inventoryTurnover: invTurn,
      daysInventory: div(v.inventory * 365, v.cogs),
      receivablesTurnover: recTurn,
      daysSales: div(v.receivables * 365, v.revenue)
    };
  }

  function times(x) { return x === null ? 'n/a' : dec.format(x); }
  function percent(x) { return x === null ? 'n/a' : one.format(x * 100) + '%'; }
  function days(x) { return x === null ? 'n/a' : one.format(x) + ' days'; }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var v = {};
    FIELDS.forEach(function (id) {
      var key = id.slice(2);
      v[key.charAt(0).toLowerCase() + key.slice(1)] = num(id);
    });
    var error = document.getElementById('frError');
    var vals = FIELDS.map(num);
    var bad = vals.some(isNaN) || FIELDS.some(function (id) { return id !== 'frOther' && id !== 'frTaxes' && num(id) < 0; });
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Fill in every field with a number. Only other income and income taxes can be negative.';
      return;
    }
    var r = compute(v);
    set('frCurrent', times(r.current));
    set('frNetMargin', percent(r.netMargin));
    set('frDebtEquity', times(r.debtToEquity));
    set('frRoe', percent(r.roe));
    set('frGross', money.format(r.gross));
    set('frOperating', money.format(r.operating));
    set('frNet', money.format(r.net));
    set('frEquity', money.format(r.equity));
    set('frWorkingCap', money.format(r.workingCapital));
    set('frRQuick', times(r.quick));
    set('frRCash', times(r.cash));
    set('frRCurrent', times(r.current));
    set('frRGrossMargin', percent(r.grossMargin));
    set('frROperatingMargin', percent(r.operatingMargin));
    set('frRNetMargin', percent(r.netMargin));
    set('frRRoa', percent(r.roa));
    set('frRRoe', percent(r.roe));
    set('frRDebtEquity', times(r.debtToEquity));
    set('frRDebtRatio', percent(r.debtRatio));
    set('frRCoverage', times(r.interestCoverage));
    set('frRAssetTurn', times(r.assetTurnover));
    set('frRInvTurn', times(r.inventoryTurnover));
    set('frRDaysInv', days(r.daysInventory));
    set('frRRecTurn', times(r.receivablesTurnover));
    set('frRDso', days(r.daysSales));

    var warn = [];
    if (v.cash + v.receivables + v.inventory > v.curAssets) warn.push('Cash, receivables and inventory add up to more than total current assets.');
    if (v.curAssets > v.assets) warn.push('Current assets are larger than total assets.');
    if (v.curLiab > v.liab) warn.push('Current liabilities are larger than total liabilities.');
    if (r.equity <= 0) warn.push('Liabilities are equal to or larger than assets, so equity is zero or negative and return on equity and debt-to-equity are not meaningful.');
    var box = document.getElementById('frWarning');
    box.hidden = warn.length === 0;
    set('frWarningText', warn.join(' '));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('frForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
